-- 0014_SeedAdminUser.sql
--
-- Seeds exactly one bootstrap Admin account. RegisterUserCommand
-- requires an authenticated Admin to run (by design — account
-- creation should never be anonymous), which means the very first
-- Admin can't be created through the app itself. This migration is
-- that one necessary exception, seeded directly rather than adding
-- a second anonymous-registration code path.
--
-- IMPORTANT: PasswordHash below must be generated by actually calling
-- PasswordHasher.Hash("1Passcode.") once and pasting the real output
-- here — do not trust a hardcoded value without verifying it round-trips
-- through PasswordHasher.Verify first. Change this password immediately
-- after first login.

INSERT INTO auth.[User] (Id, Username, PasswordHash, Role, IsActive)
VALUES (NEWID(), 'admin', '100000.Gtg7GeNGSLKPng5DkuUNCw==.LtmPA3RT8M3xCVbv6GO6oY8W0iSEk3JkHLd0cMTQKNA=', 'Admin', 1);
